  override func wr(_ arcn : ARCHD) -> Result {
    HD_VCPIO *hd;
    unsigned int nsz;
    HD_VCPIO hdblk;

    /*
     * check and repair truncated device and inode fields in the cpio
     * header
     */
    if (map_dev(arcn, (u_long)VCPIO_MASK, (u_long)VCPIO_MASK) < 0) {
